if(['product','product_update'].includes(kind)){let p=kind==='product_update'?pget(arg):{name:'',en:'',sku:'',barcode:'',category:s.categories[0]?.id,brand:s.brands[0]?.id,unit:s.units[0]?.code||'pcs',price:0,currency:'IRR',min:0,target:0,tracking:'none',policy:'FIFO',description:'',attributes:{},group:'',image:''};let image=p.image||'';let html=field('name','text',p.name)+field('en','text',p.en,false)+field('sku','text',p.sku)+field('barcode','text',p.barcode,false)+select('category',[blank(),...s.categories.map(x=>[x.id,name(x)])],p.category)+select('brand',[blank(),...s.brands.map(x=>[x.id,name(x)])],p.brand)+select('unit',s.units.map(x=>[x.code,name(x)]),p.unit)+field('price','number',p.price)+select('currency',currencies,p.currency)+field('min','number',p.min)+field('target','number',p.target)+select('tracking',['none','lot','serial'].map(x=>[x,t(x)]),p.tracking)+select('policy',[['FIFO',t('FIFO')],['FEFO',t('FEFO')]],p.policy)+field('group','text',p.group,false)+area('description',p.description)+area('attributes',Object.entries(p.attributes||{}).map(([k,v])=>k+': '+v).join('\n'))+`<label class="full">${t('image')}<input id="product-image" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG / JPEG / WebP · ${prefs.lang==='fa'?'حداکثر ۶۵۰ کیلوبایت':'up to 650 KB'}</small></label><img id="image-preview" src="${esc(image||'icon.svg')}" alt="" style="width:80px;height:80px;object-fit:cover;border-radius:10px">`;let d=show(kind==='product'?'newProduct':'edit',html,async b=>{let attributes={};for(let line of b.attributes.split('\n').filter(x=>x.trim())){let i=line.indexOf(':');if(i<1)throw Error('Invalid custom fields');attributes[line.slice(0,i).trim()]=line.slice(i+1).trim()}await mutate({...b,attributes,image,type:kind,...(kind==='product_update'?{id:p.id,expectedRecordVersion:p._revision||0}:{})})},true);d.querySelector('#product-image').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;if(f.size>650000)throw Error('Image must be PNG/JPEG/WebP under 650 KB');image=await new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(f)});d.querySelector('#image-preview').src=image}catch(e){toast(errorText(e));d.querySelector('#product-image').value=''}};return d}
