if(kind==='transfer_receive'){let tr=s.transfers.find(x=>x.id===arg);return show('confirmReceive',`<p class="notice full">${esc(name(pget(tr.product)))} · ${esc(name(wget(tr.to)))} · ${t('remaining')}: ${n(tr.qty-tr.received)}</p>${field('qty','number',tr.qty-tr.received,true,`max="${tr.qty-tr.received}"`)}${select('location',locations(tr.to))}`,submit(kind,{id:tr.id}))}
if(kind==='count_create'){let d=show('newCount',select('warehouse',ws)+field('reason')+`<label class="check-row full"><input name="blind" type="checkbox" checked>${t('blind')}</label><div class="full" id="count-lines"></div>`,async(b,form)=>{let lines=[...form.querySelectorAll('[data-count-layer]')].filter(i=>i.value!=='').map(i=>({layer:i.dataset.countLayer,qty:i.value}));await mutate({type:kind,warehouse:b.warehouse,reason:b.reason,blind:b.blind==='on',lines})},true);let render=()=>{let w=d.querySelector('[name=warehouse]').value;$('#count-lines').innerHTML=`<p class="notice">${prefs.lang==='fa'?'فقط ردیف‌های شمارش‌شده را پر کنید. صفر قابل ثبت است. اختلاف پس از تأیید مدیر اعمال می‌شود.':'Fill only counted layers. Zero is valid. Adjustments apply after manager approval.'}</p><div class="table-wrap"><table><thead><tr><th>${t('product')}</th><th>${t('lot')}</th><th>${t('expected')}</th><th>${t('counted')}</th></tr></thead><tbody>${s.stock.filter(b=>b.warehouse===w).map(b=>`<tr><td>${esc(name(pget(b.product)))}</td><td>${esc(b.lot||b.serial||'—')}</td><td data-expected>${n(b.qty)}</td><td><input aria-label="${esc(layerName(b))}" data-count-layer="${b.id}" type="number" min="0" step="${b.serial?'1':'0.000001'}"></td></tr>`).join('')}</tbody></table></div>`};d.querySelector('[name=warehouse]').onchange=()=>{render();hideExpected()};const hideExpected=()=>d.querySelectorAll('[data-expected]').forEach(el=>el.textContent=d.querySelector('[name=blind]').checked?'—':n(s.stock.find(b=>b.id===el.nextElementSibling?.querySelector('[data-count-layer]')?.dataset.countLayer)?.qty||0));d.querySelector('[name=blind]').onchange=hideExpected;render();hideExpected();return d}
if(kind==='order'||kind==='reorder'){let [reorderProduct,reorderWarehouse,reorderQty]=arg?.split('|')||[];let orderKind=kind==='reorder'?'purchase':arg,initialProduct=kind==='reorder'?pget(reorderProduct):null,priceLists=[...new Set(s.prices.map(p=>p.name))];let html=select('warehouse',ws,reorderWarehouse||ws[0]?.[0])+select('contact',s.contacts.filter(c=>c.type===(orderKind==='purchase'?'supplier':'customer')).map(c=>[c.id,c.name]))+field('due','date','',false)+select('priceList',[blank(t('basePrice')),...priceLists.map(x=>[x,x])])+area('note')+(orderKind==='sales'?`<label class="check-row full"><input name="allowBackorder" type="checkbox">${t('allowBackorder')}</label><label class="check-row full"><input name="scanRequired" type="checkbox">${t('scanRequired')}</label>`:'')+`<div class="line-list full"><h3>${t('lines')}</h3><div id="order-lines"></div><button type="button" id="add-line">+ ${t('addLine')}</button></div><p class="notice full">${t('dateHint')} · ${prefs.lang==='fa'?'فروش هنگام ثبت، موجودی را رزرو می‌کند. اقلام رهگیری‌شده به صورت خودکار تخصیص می‌یابند.':'Sales reserve stock immediately. Tracked units are allocated automatically.'}</p>`;let d=show('newOrder',html,async(b,form)=>{let lines=[...form.querySelectorAll('.order-line')].map(row=>({product:row.querySelector('[data-product]').value,qty:row.querySelector('[data-qty]').value,unit:row.querySelector('[data-unit]').value}));await mutate({type:'order',kind:orderKind,warehouse:b.warehouse,contact:b.contact,due:b.due,note:b.note,priceList:b.priceList,allowBackorder:b.allowBackorder==='on',scanRequired:b.scanRequired==='on',lines})},true);
const add=(p=ps[0]?.[0],q=1)=>{let row=document.createElement('div');row.className='order-line';row.innerHTML=`<label>${t('product')}<select data-product required>${ps.map(([v,l])=>`<option value="${v}" ${p===v?'selected':''}>${esc(l)}</option>`).join('')}</select></label><label>${t('unit')}<select data-unit></select></label><label>${t('qty')}<input type="number" data-qty min="0.000001" step="0.000001" value="${q}" required></label><button type="button" data-remove aria-label="${t('remove')}">×</button>`;const sync=()=>{let selected=pget(row.querySelector('[data-product]').value);row.querySelector('[data-unit]').innerHTML=[selected.unit,...selected.conversions.map(c=>c.unit)].map(code=>'<option value="'+esc(code)+'">'+esc(name(s.units.find(u=>u.code===code))||unit(code))+'</option>').join('')};row.querySelector('[data-product]').onchange=sync;sync();row.querySelector('[data-remove]').onclick=()=>row.remove();$('#order-lines').append(row)};$('#add-line').onclick=()=>add();add(initialProduct?.id,initialProduct?Math.max(1,Number(reorderQty)||initialProduct.target-available(s,initialProduct.id,reorderWarehouse)):1);return d}
if(['order_receive','dispatch','return'].includes(kind)){let o=s.orders.find(x=>x.id===arg);let html=`<p class="notice full">${esc(o.number)} · ${esc(name(wget(o.warehouse)))}${kind==='return'?' · '+t('returnHint'):''}</p><div class="full">${o.lines.map((l,i)=>{let p=pget(l.product),remaining=kind==='order_receive'?l.qty-l.received:kind==='dispatch'?l.qty-l.dispatched:l.dispatched-l.returned;return `<div class="fulfill-line" data-line="${i}"><h3>${esc(name(p))} · ${p.sku} · ${t('remaining')}: ${n(remaining)}</h3><div class="fields">${field('qty_'+i,'number',remaining,true,`max="${remaining}"`)}${kind==='order_receive'?select('unit_'+i,[[p.unit,unit(p.unit)],...p.conversions.map(c=>[c.unit,unit(c.unit)])],p.unit)+select('location_'+i,locations(o.warehouse))+field('lot_'+i,'text','',false)+field('expiry_'+i,'date','',false)+(p.tracking==='serial'?area('serials_'+i):''):''}</div></div>`}).join('')}</div>`+(kind==='dispatch'?field('carrier','text','',false)+field('shipmentTracking','text','',false):'');
let d=show(kind==='order_receive'?'confirmReceive':kind,html,async(b)=>{let lines=o.lines.map((l,i)=>({index:i,qty:b['qty_'+i],unit:b['unit_'+i],location:b['location_'+i],lot:b['lot_'+i],expiry:b['expiry_'+i],serials:b['serials_'+i]}));await mutate({type:kind,id:o.id,lines,carrier:b.carrier,tracking:b.shipmentTracking})},true);
for(let i=0;i<o.lines.length;i++){let u=d.querySelector(`[name=unit_${i}]`),q=d.querySelector(`[name=qty_${i}]`);if(u)u.onchange=()=>{let l=o.lines[i],p=pget(l.product),factor=u.value===p.unit?1:p.conversions.find(c=>c.unit===u.value).factor;q.value=(l.qty-l.received)/factor;q.max=q.value}}
// Dynamic field labels are translated here without changing their unique input names.
for(let i=0;i<o.lines.length;i++)for(let key of ['qty','unit','location','lot','expiry','serials']){let el=d.querySelector(`[name="${key}_${i}"]`);if(el&&el.parentElement.firstChild.nodeType===Node.TEXT_NODE)el.parentElement.firstChild.textContent=t(key)}return d}
if(kind==='price')return show('pricing',field('name')+select('product',ps)+field('amount','number',0)+select('currency',currencies,'IRR')+field('validFrom','date','',false)+field('validTo','date','',false),submit(kind));
