if(kind==='user'){let u=arg?meta.users.find(u=>u.id===arg):null;let d=show('users',field('username','text',u?.username||'',true,u?'readonly':'pattern="[a-zA-Z0-9_.-]{3,50}"')+field('name','text',u?.name||'')+select('role',[...Object.keys(roles).map(r=>[r,t(r==='warehouse'?'warehouseRole':r)]),...s.customRoles.map(r=>[r.id,r.name])],u?.role||'viewer')+field('password','password','',!u,'minlength="12" autocomplete="new-password"')+`<label class="full">${t('warehouseAccess')}<select name="warehouseIds" multiple size="4">${ws.map(([id,label])=>`<option value="${id}" ${u?.warehouses.includes(id)?'selected':''}>${esc(label)}</option>`).join('')}</select></label>`+(u?`<label class="check-row"><input type="checkbox" name="active" ${u.active?'checked':''}>${t('active')}</label>`:''),async(b,f)=>{let warehouses=[...f.querySelector('[name=warehouseIds]').selectedOptions].map(o=>o.value);await api('users',{...b,...(u?{id:u.id}:{}),warehouses,active:u?!!b.active:true});await refresh()},true);return d}
if(kind==='password')return show('changePassword',field('currentPassword','password')+field('newPassword','password','',true,'minlength="12"'),async b=>{await api('password',{current:b.currentPassword,password:b.newPassword});toast(t('ok'))});
